271→       export type SdkEventHandler = (event: SdkEvent) => void;
272→
273→       /**
274→        * Simple typed event emitter. No external dependencies.
275→        * Consumers subscribe with on() and unsubscribe with off().
276→        */
277→       export class SdkEventEmitter {
278→         private handlers: SdkEventHandler[] = [];
279→
280→         on(handler: SdkEventHandler): () => void {
281→           this.handlers.push(handler);
282→           return () => this.off(handler);
283→         }
284→
285→         off(handler: SdkEventHandler): void {
286→           this.handlers = this.handlers.filter((h) => h !== handler);
287→         }
288→
289→         emit(event: SdkEvent): void {
290→           for (const handler of this.handlers) {
291→             try { handler(event); } catch { /* subscriber errors don't crash SDK */ }
