 10→/**
 11→ * Upload encrypted file to IPFS via backend relay.
 12→ * Uses axios directly for upload progress tracking (CancelToken not available in apiClient).
 13→ */
 14→export async function addToIpfs(
 15→  encryptedFile: Blob,
 16→  onProgress?: (percent: number) => void,
 17→  cancelToken?: CancelToken
 18→): Promise<AddResponse> {
 19→  const { accessToken } = useAuthStore.getState();
 20→
 21→  const formData = new FormData();
 22→  formData.append('file', encryptedFile);
 23→
 24→  const response = await axios.post<AddResponse>(`${BASE_URL}/ipfs/upload`, formData, {
 25→    headers: { Authorization: `Bearer ${accessToken}` },
 26→    onUploadProgress: (event: AxiosProgressEvent) => {
 27→      if (event.total && onProgress) {
 28→        const percent = Math.round((event.loaded * 100) / event.total);
 29→        onProgress(percent);
 30→      }
 31→    },
 32→    cancelToken,
 33→  });
 34→
 35→  return response.data;
 36→}
