 50→/**
 51→ * Fetch encrypted file from IPFS via the API proxy.
 52→ * Supports progress tracking for larger files.
 53→ *
 54→ * @param cid - IPFS CID of the file
 55→ * @param onProgress - Optional callback for download progress
 56→ * @returns Encrypted file content as Uint8Array
 57→ */
 58→export async function fetchFromIpfs(
 59→  cid: string,
 60→  onProgress?: DownloadProgressCallback
 61→): Promise<Uint8Array> {
 62→  const { accessToken } = useAuthStore.getState();
 63→  const response = await fetch(`${BASE_URL}/ipfs/${cid}`, {
 64→    headers: {
 65→      Authorization: `Bearer ${accessToken}`,
 66→    },
 67→  });
 68→
 69→  if (!response.ok) {
 70→    throw new Error(`Failed to fetch from IPFS: ${response.status}`);
 71→  }
 72→
 73→  // If no progress callback or no content-length, just return arrayBuffer
 74→  const contentLength = response.headers.get('Content-Length');
 75→  if (!onProgress || !contentLength) {
 76→    const buffer = await response.arrayBuffer();
 77→    return new Uint8Array(buffer);
 78→  }
 79→
 80→  // Stream with progress
 81→  const total = parseInt(contentLength, 10);
 82→  const reader = response.body?.getReader();
 83→  if (!reader) {
 84→    throw new Error('ReadableStream not supported');
 85→  }
 86→
 87→  const chunks: Uint8Array[] = [];
 88→  let loaded = 0;
 89→
 90→  while (true) {
 91→    const { done, value } = await reader.read();
 92→    if (done) break;
 93→
 94→    chunks.push(value);
 95→    loaded += value.length;
 96→    onProgress(loaded, total);
 97→  }
 98→
 99→  // Combine chunks
100→  const result = new Uint8Array(loaded);
101→  let offset = 0;
102→  for (const chunk of chunks) {
103→    result.set(chunk, offset);
104→    offset += chunk.length;
105→  }
106→
107→  return result;
108→}
